SELECT CASE WHEN (scientific_name='Homo sapiens' OR starts_with(scientific_name,'Homo sapiens ')) THEN 'Homo sapiens' WHEN (scientific_name='Zea mays' OR starts_with(scientific_name,'Zea mays ')) THEN 'Zea mays' WHEN (scientific_name='Picea abies' OR starts_with(scientific_name,'Picea abies ')) THEN 'Picea abies' WHEN (scientific_name='Chenopodium quinoa' OR starts_with(scientific_name,'Chenopodium quinoa ')) THEN 'Chenopodium quinoa' WHEN (scientific_name='Sus scrofa' OR starts_with(scientific_name,'Sus scrofa ')) THEN 'Sus scrofa' WHEN (scientific_name='Mus musculus' OR starts_with(scientific_name,'Mus musculus ')) THEN 'Mus musculus' WHEN (scientific_name='Triticum aestivum' OR starts_with(scientific_name,'Triticum aestivum ')) THEN 'Triticum aestivum' WHEN (scientific_name='Solanum tuberosum' OR starts_with(scientific_name,'Solanum tuberosum ')) THEN 'Solanum tuberosum' WHEN ((scientific_name='Penaeus vannamei' OR starts_with(scientific_name,'Penaeus vannamei ')) OR scientific_name='Litopenaeus vannamei' OR starts_with(scientific_name,'Litopenaeus vannamei ')) THEN 'Penaeus vannamei' WHEN (scientific_name='Gallus gallus' OR starts_with(scientific_name,'Gallus gallus ')) THEN 'Gallus gallus' WHEN (scientific_name='Arabidopsis thaliana' OR starts_with(scientific_name,'Arabidopsis thaliana ')) THEN 'Arabidopsis thaliana' WHEN (scientific_name='Oryza sativa' OR starts_with(scientific_name,'Oryza sativa ')) THEN 'Oryza sativa' WHEN (scientific_name='Saccharomyces cerevisiae' OR starts_with(scientific_name,'Saccharomyces cerevisiae ')) THEN 'Saccharomyces cerevisiae' WHEN (scientific_name='Severe acute respiratory syndrome coronavirus 2' OR starts_with(scientific_name,'Severe acute respiratory syndrome coronavirus 2 ')) THEN 'Severe acute respiratory syndrome coronavirus 2' WHEN ((scientific_name='Mycobacterium tuberculosis' OR starts_with(scientific_name,'Mycobacterium tuberculosis ')) AND NOT starts_with(scientific_name,'Mycobacterium tuberculosis complex')) THEN 'Mycobacterium tuberculosis' WHEN (scientific_name='Escherichia coli' OR starts_with(scientific_name,'Escherichia coli ')) THEN 'Escherichia coli' WHEN (scientific_name='Cricetulus griseus' OR starts_with(scientific_name,'Cricetulus griseus ')) THEN 'Cricetulus griseus' WHEN scientific_name='freshwater metagenome' THEN 'freshwater metagenome' WHEN scientific_name='food fermentation metagenome' THEN 'food fermentation metagenome' WHEN scientific_name='soil metagenome' THEN 'soil metagenome' WHEN scientific_name='human gut metagenome' THEN 'human gut metagenome' WHEN scientific_name='food metagenome' THEN 'food metagenome' ELSE '[other or missing label]' END AS organism_group,
coalesce(library_source,'') AS source,coalesce(library_strategy,'') AS strategy,
coalesce(instrument_platform,'') AS platform,coalesce(instrument_model,'') AS model,
count(*) AS stock_runs,
coalesce(sum(bases) FILTER(WHERE bases>=0),0) AS stock_bases,
count(*) FILTER(WHERE bases IS NULL OR bases<0) AS stock_missing_bases,
count(*) FILTER(WHERE public_date>=DATE '2025-10-01') AS annual_runs,
coalesce(sum(bases) FILTER(WHERE public_date>=DATE '2025-10-01' AND bases>=0),0) AS annual_bases,
count(*) FILTER(WHERE public_date>=DATE '2025-10-01' AND (bases IS NULL OR bases<0)) AS annual_missing_bases
FROM runs WHERE public_date<DATE '2026-10-01' GROUP BY ALL;
